SELECT CASE WHEN COUNT(1) > 0 THEN TRUE ELSE FALSE END
FROM quests
WHERE battle_id = #{battleId}
  AND user_id = #{userId}

SELECT COUNT(1)
FROM quests
WHERE battle_id = #{battleId}

SELECT guild_id
FROM boss_battles
